1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.model.OwnerIdentity;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerException;
9	
10	/**
11	 * The single duplicate check on create, keyed on the owner's identityKey — the SHA-256 hex over
12	 * the {@code normalizedTelephone|email|soundex(lastName)} composite defined by
13	 * {@link OwnerIdentity}. Only an existing owner with the same identityKey is a hard duplicate,
14	 * rejected 409 via {@link DuplicateOwnerException}. Because the telephone is part of the key,
15	 * two owners with the same lastName and postcode but a different telephone are <em>not</em> a
16	 * hard duplicate: they may coexist as household members — which is what makes the household
17	 * membership-level ceiling meaningful — and are instead soft-flagged downstream by
18	 * {@link AssignPossibleDuplicate}. There is no separate household-duplicate block; the identityKey
19	 * is the whole duplicate rule.
20	 *
21	 * <p>{@code sharesHousehold} bypasses this block entirely: a declared household member is always
22	 * allowed (and is not flagged as a possible duplicate downstream). Runs before the owner is saved.
23	 */
24	public class EnsureUniqueOwnerIdentity {
25	
26	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
27	            throws DuplicateOwnerException {
28	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
29	            return; // declared household member bypasses the duplicate block
30	        }
31	        String identity = OwnerIdentity.of(owner);
32	        for (Owner existing : ownerRepository.findAll()) {
33	            if (Boolean.TRUE.equals(existing.getDeleted())) {
34	                continue; // soft-deleted owners do not block a create
35	            }
36	            if (identity.equals(OwnerIdentity.of(existing))) {
37	                throw new DuplicateOwnerException(identity);
38	            }
39	        }
40	    }
41	}
